'use strict';

// Quillmark markdown parser.
// Dependency-free, CommonJS, Node >= 18.
//
// Public API:
//   const { parse } = require('./src/markdown');
//   const { frontMatter, ast } = parse(markdownString);
//
// AST node types:
//   { type: 'heading', level: 1..6, children: [inline, ...] }
//   { type: 'paragraph', children: [inline, ...] }
//   { type: 'ulist', items: [ { type: 'listItem', children: [inline, ...] }, ... ] }
//   { type: 'olist', items: [ { type: 'listItem', children: [inline, ...] }, ... ] }
//   { type: 'codeBlock', lang: string, code: string }
//
// Inline node types:
//   { type: 'text', content: string }
//   { type: 'bold', content: string }
//   { type: 'italic', content: string }
//   { type: 'code', content: string }
//   { type: 'link', content: string, href: string }

function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Parse an optional `---` fenced YAML-ish front-matter block.
// Returns { frontMatter, body } where body is the markdown with the block stripped.
// Tolerant: if there is an opening `---` but no closing `---`, the whole file is
// treated as body and no front-matter is extracted.
function parseFrontMatter(content) {
  const lines = content.split('\n');
  let frontMatter = {};
  let bodyStart = 0;

  if (lines.length > 0 && lines[0].trim() === '---') {
    let closeIdx = -1;
    for (let i = 1; i < lines.length; i++) {
      if (lines[i].trim() === '---') {
        closeIdx = i;
        break;
      }
    }
    if (closeIdx !== -1) {
      for (let i = 1; i < closeIdx; i++) {
        const m = lines[i].match(/^([A-Za-z_][A-Za-z0-9_]*)\s*:\s*(.*)$/);
        if (m) {
          const key = m[1];
          let value = m[2].replace(/\s+$/, '');
          if (key === 'tags') {
            frontMatter[key] = value.split(',').map(s => s.trim()).filter(Boolean);
          } else {
            frontMatter[key] = value;
          }
        }
      }
      bodyStart = closeIdx + 1;
    }
    // No closing fence -> treat entire file as body (frontMatter stays {}).
  }

  const body = lines.slice(bodyStart).join('\n');
  return { frontMatter, body };
}

// Parse inline markdown into a flat array of inline nodes.
// Order of precedence: code -> bold -> italic -> link -> plain text.
// Nesting is not fully supported; nested cases render in a reasonable way.
function parseInline(text) {
  const children = [];
  let i = 0;
  const n = text.length;
  while (i < n) {
    const rest = text.slice(i);
    let m;

    // Inline code: `code`
    if ((m = rest.match(/^(`)([^`]+?)\1/))) {
      children.push({ type: 'code', content: m[2] });
      i += m[0].length;
      continue;
    }
    // Bold: **bold**
    if ((m = rest.match(/^(\*\*)([^*]+?)\1/))) {
      children.push({ type: 'bold', content: m[2] });
      i += m[0].length;
      continue;
    }
    // Italic: *italic*
    if ((m = rest.match(/^(\*)([^*]+?)\1/))) {
      children.push({ type: 'italic', content: m[2] });
      i += m[0].length;
      continue;
    }
    // Link: [text](url)
    if ((m = rest.match(/^(\[)([^\]]+)\]\(([^)]*)\)/))) {
      children.push({ type: 'link', content: m[2], href: m[3] });
      i += m[0].length;
      continue;
    }

    // Plain text: accumulate until the next inline marker character.
    let next = n;
    for (const marker of ['`', '*', '[']) {
      const idx = rest.indexOf(marker);
      if (idx !== -1 && idx < next) next = idx;
    }
    if (next === 0) {
      // A marker character that did not form a valid inline construct.
      children.push({ type: 'text', content: rest[0] });
      i += 1;
    } else {
      children.push({ type: 'text', content: rest.slice(0, next) });
      i += next;
    }
  }
  return children;
}

// Parse a markdown string into { frontMatter, ast }.
function parse(content) {
  const normalized = content.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const { frontMatter, body } = parseFrontMatter(normalized);
  const lines = body.split('\n');
  const ast = [];
  let i = 0;
  const n = lines.length;

  while (i < n) {
    const line = lines[i];

    // Blank lines separate blocks; skip them.
    if (line.trim() === '') {
      i += 1;
      continue;
    }

    // Fenced code block: ```
    if (line.match(/^```/)) {
      const fenceMatch = line.match(/^```(\w*)/);
      const lang = fenceMatch ? fenceMatch[1] : '';
      const codeLines = [];
      i += 1;
      while (i < n && !lines[i].match(/^```/)) {
        codeLines.push(lines[i]);
        i += 1;
      }
      if (i < n) i += 1; // consume closing fence
      ast.push({ type: 'codeBlock', lang, code: codeLines.join('\n') });
      continue;
    }

    // Heading: # .. ######
    const h = line.match(/^(#{1,6})\s+(.*)$/);
    if (h) {
      ast.push({ type: 'heading', level: h[1].length, children: parseInline(h[2]) });
      i += 1;
      continue;
    }

    // Unordered list: - item
    if (line.match(/^- /)) {
      const items = [];
      while (i < n && lines[i].match(/^- /)) {
        items.push({ type: 'listItem', children: parseInline(lines[i].slice(2)) });
        i += 1;
      }
      ast.push({ type: 'ulist', items });
      continue;
    }

    // Ordered list: 1. item
    if (line.match(/^\d+\. /)) {
      const items = [];
      while (i < n && lines[i].match(/^\d+\. /)) {
        items.push({ type: 'listItem', children: parseInline(lines[i].replace(/^\d+\. /, '')) });
        i += 1;
      }
      ast.push({ type: 'olist', items });
      continue;
    }

    // Paragraph: consecutive non-blank lines that are not a block start.
    const paraLines = [];
    while (
      i < n &&
      lines[i].trim() !== '' &&
      !lines[i].match(/^```/) &&
      !lines[i].match(/^#{1,6}\s+/) &&
      !lines[i].match(/^- /) &&
      !lines[i].match(/^\d+\. /)
    ) {
      paraLines.push(lines[i]);
      i += 1;
    }
    ast.push({ type: 'paragraph', children: parseInline(paraLines.join(' ')) });
  }

  return { frontMatter, ast };
}

module.exports = { parse, escapeHtml };

'use strict';

// Quillmark HTML renderer.
// Dependency-free, CommonJS, Node >= 18.
//
// Public API:
//   const { render } = require('./src/render');
//   const html = render({ frontMatter, ast }, { title?: string });

const { escapeHtml } = require('./src/markdown');

// Inline CSS, self-contained, no external assets, no CDN.
const CSS = `
* { box-sizing: border-box; }
body { font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; line-height: 1.6; color: #1a1a1a; max-width: 720px; margin: 2rem auto; padding: 0 1rem; }
h1, h2, h3, h4, h5, h6 { color: #0f172a; margin-top: 1.5rem; }
h1 { font-size: 2rem; border-bottom: 2px solid #e2e8f0; padding-bottom: 0.5rem; }
h2 { font-size: 1.5rem; border-bottom: 1px solid #e2e8f0; padding-bottom: 0.35rem; }
h3 { font-size: 1.25rem; }
p { margin: 1rem 0; }
ul, ol { margin: 1rem 0 1rem 1.5rem; }
li { margin: 0.35rem 0; }
pre { background: #f1f5f9; border: 1px solid #e2e8f0; border-radius: 6px; padding: 1rem; overflow-x: auto; }
code { background: #f1f5f9; padding: 0.15rem 0.4rem; border-radius: 4px; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.9em; }
pre code { padding: 0; background: transparent; font-size: 1em; }
a { color: #2563eb; text-decoration: underline; }
`;

function renderInline(children) {
  let html = '';
  for (const c of children) {
    switch (c.type) {
      case 'text':
        html += escapeHtml(c.content);
        break;
      case 'bold':
        html += '<strong>' + escapeHtml(c.content) + '</strong>';
        break;
      case 'italic':
        html += '<em>' + escapeHtml(c.content) + '</em>';
        break;
      case 'code':
        html += '<code>' + escapeHtml(c.content) + '</code>';
        break;
      case 'link':
        html += '<a href="' + escapeHtml(c.href) + '">' + escapeHtml(c.content) + '</a>';
        break;
      default:
        html += escapeHtml(String(c.content));
    }
  }
  return html;
}

// Flatten inline nodes to plain text (used for the page title).
function plainText(children) {
  return children.map(c => {
    if (c.type === 'link') return c.content;
    if (c.type === 'text' || c.type === 'bold' || c.type === 'italic' || c.type === 'code') {
      return c.content;
    }
    return '';
  }).join('');
}

function renderBlock(node) {
  switch (node.type) {
    case 'heading':
      return '<h' + node.level + '>' + renderInline(node.children) + '</h' + node.level + '>';
    case 'paragraph':
      return '<p>' + renderInline(node.children) + '</p>';
    case 'ulist': {
      const items = node.items.map(it => '<li>' + renderInline(it.children) + '</li>').join('');
      return '<ul>' + items + '</ul>';
    }
    case 'olist': {
      const items = node.items.map(it => '<li>' + renderInline(it.children) + '</li>').join('');
      return '<ol>' + items + '</ol>';
    }
    case 'codeBlock': {
      const langClass = node.lang ? ' class="lang-' + escapeHtml(node.lang) + '"' : '';
      return '<pre><code' + langClass + '>' + escapeHtml(node.code) + '</code></pre>';
    }
    default:
      return '';
  }
}

function render(doc, opts) {
  opts = opts || {};
  const frontMatter = doc.frontMatter || {};
  const ast = doc.ast || [];

  // Resolve page title: --title override > front-matter title > first heading.
  let title = opts.title;
  if (!title) title = frontMatter.title || '';
  if (!title) {
    for (const node of ast) {
      if (node.type === 'heading') {
        title = plainText(node.children);
        break;
      }
    }
  }

  const bodyHtml = ast.map(renderBlock).join('\n');

  return (
    '<!DOCTYPE html>\n' +
    '<html lang="en">\n' +
    '<head>\n' +
    '<meta charset="utf-8">\n' +
    '<title>' + escapeHtml(title) + '</title>\n' +
    '<style>' + CSS + '</style>\n' +
    '</head>\n' +
    '<body>\n' +
    bodyHtml +
    '\n</body>\n' +
    '</html>\n'
  );
}

module.exports = { render, CSS };

#!/usr/bin/env node
'use strict';

const fs = require('fs');
const markdown = require('./src/markdown');
const render = require('./src/render');

function printUsage() {
  process.stdout.write(
    'Usage: node src/cli.js <input.md> [-o <out.html>] [--title <title>]\n'
  );
}

function parseArgs(args) {
  const options = { input: null, output: null, title: null };
  let i = 0;
  while (i < args.length) {
    const a = args[i];
    if (a === '-o') {
      if (i + 1 >= args.length) {
        return { error: 'Option -o requires a value' };
      }
      options.output = args[i + 1];
      i += 2;
    } else if (a === '--title') {
      if (i + 1 >= args.length) {
        return { error: 'Option --title requires a value' };
      }
      options.title = args[i + 1];
      i += 2;
    } else if (a === '--help' || a === '-h') {
      printUsage();
      process.exit(0);
    } else if (options.input === null) {
      options.input = a;
      i += 1;
    } else {
      return { error: 'Unknown argument: ' + a };
    }
  }
  if (!options.input) {
    return { error: 'Missing input file' };
  }
  return options;
}

function main() {
  const result = parseArgs(process.argv.slice(2));
  if (result.error) {
    process.stderr.write('Error: ' + result.error + '\n');
    printUsage();
    process.exit(1);
  }

  const { input, output, title } = result;

  if (!fs.existsSync(input)) {
    process.stderr.write('Error: input file not found: ' + input + '\n');
    process.exit(1);
  }

  const content = fs.readFileSync(input, 'utf8');
  const doc = markdown.parse(content);
  const html = render.render(doc, { title });

  if (output) {
    fs.writeFileSync(output, html, 'utf8');
  } else {
    process.stdout.write(html);
  }
  process.exit(0);
}

main();

#!/usr/bin/env node
'use strict';

// Quillmark test suite — dependency-free, CommonJS, Node >= 18.
const fs = require('fs');
const { execSync } = require('child_process');
const { parse, escapeHtml } = require('../src/markdown');
const { render } = require('../src/render');

let passes = 0;
let failures = 0;

function assert(condition, name, detail) {
  if (condition) {
    passes += 1;
    process.stdout.write('PASS ' + name + '\n');
  } else {
    failures += 1;
    process.stdout.write('FAIL ' + name + ' — ' + (detail || '') + '\n');
  }
}

function childrenText(node) {
  return (node.children || []).map(c => c.content || '').join('');
}

// 1. Front matter
{
  const { frontMatter, ast } = parse('---\ntitle: Hello\ntags: a, b\n---\n# Hi');
  assert(frontMatter.title === 'Hello', 'front-matter title');
  assert(Array.isArray(frontMatter.tags) && frontMatter.tags[0] === 'a' && frontMatter.tags[1] === 'b', 'front-matter tags array');
  assert(ast.length === 1 && ast[0].type === 'heading' && ast[0].level === 1, 'front-matter heading');
  assert(childrenText(ast[0]) === 'Hi', 'front-matter heading text');
}

// 2. No front matter
{
  const { frontMatter, ast } = parse('# Just a title');
  assert(JSON.stringify(frontMatter) === '{}', 'no front-matter empty object');
  assert(ast.length === 1 && ast[0].type === 'heading', 'no front-matter heading');
}

// 3. Heading levels
{
  for (let lvl = 1; lvl <= 6; lvl++) {
    const prefix = '#'.repeat(lvl) + ' ';
    const { ast } = parse(prefix + 'h' + lvl);
    assert(ast[0] && ast[0].type === 'heading' && ast[0].level === lvl, 'heading level ' + lvl);
  }
}

// 4. Paragraph
{
  const { ast } = parse('Just text.');
  assert(ast.length === 1 && ast[0].type === 'paragraph', 'paragraph node');
  assert(childrenText(ast[0]) === 'Just text.', 'paragraph text');
}

// 5. Unordered list
{
  const { ast } = parse('- a\n- b');
  assert(ast.length === 1 && ast[0].type === 'ulist', 'ulist node');
  assert(ast[0].items.length === 2, 'ulist two items');
  assert(ast[0].items[0].type === 'listItem', 'ulist listItem type');
  assert(childrenText(ast[0].items[0]) === 'a', 'ulist first item');
  assert(childrenText(ast[0].items[1]) === 'b', 'ulist second item');
}

// 6. Ordered list
{
  const { ast } = parse('1. a\n2. b');
  assert(ast.length === 1 && ast[0].type === 'olist', 'olist node');
  assert(ast[0].items.length === 2, 'olist two items');
  assert(childrenText(ast[0].items[0]) === 'a', 'olist first item');
  assert(childrenText(ast[0].items[1]) === 'b', 'olist second item');
}

// 7. Fenced code block
{
  const { ast } = parse('```js\nconst x = 1\n```');
  assert(ast.length === 1 && ast[0].type === 'codeBlock', 'codeBlock node');
  assert(ast[0].lang === 'js', 'codeBlock lang js');
  assert(ast[0].code === 'const x = 1', 'codeBlock code');
}

// 8. Inline bold
{
  const { ast } = parse('**bold**');
  assert(ast[0].children.length === 1 && ast[0].children[0].type === 'bold', 'bold inline');
  assert(ast[0].children[0].content === 'bold', 'bold content');
}

// 9. Inline italic
{
  const { ast } = parse('*italic*');
  assert(ast[0].children.length === 1 && ast[0].children[0].type === 'italic', 'italic inline');
  assert(ast[0].children[0].content === 'italic', 'italic content');
}

// 10. Inline code
{
  const { ast } = parse('`code`');
  assert(ast[0].children.length === 1 && ast[0].children[0].type === 'code', 'code inline');
  assert(ast[0].children[0].content === 'code', 'code content');
}

// 11. Inline link
{
  const { ast } = parse('[text](http://example.com)');
  assert(ast[0].children.length === 1 && ast[0].children[0].type === 'link', 'link inline');
  assert(ast[0].children[0].content === 'text', 'link content');
  assert(ast[0].children[0].href === 'http://example.com', 'link href');
}

// 12. render() structure
{
  const doc = parse('---\ntitle: Hello\n---\n# Hi');
  const html = render(doc);
  assert(html.startsWith('<!DOCTYPE html>'), 'render doctype');
  assert(html.includes('<title>Hello</title>'), 'render title from front matter');
  assert(html.includes('<style>'), 'render has style');
  assert(html.includes('<h1>Hi</h1>'), 'render heading');
}

// 13. render title override
{
  const doc = parse('# Hi');
  const html = render(doc, { title: 'Custom' });
  assert(html.includes('<title>Custom</title>'), 'render title override');
}

// 14. CLI
{
  const out = '/tmp/quillmark-out.html';
  try {
    execSync('node src/cli.js site/index.md -o ' + out, { stdio: 'pipe' });
    const html = fs.readFileSync(out, 'utf8');
    assert(html.startsWith('<!DOCTYPE html>'), 'cli output doctype');
    assert(html.includes('<title>Welcome to Quillmark</title>'), 'cli output title');
  } catch (e) {
    assert(false, 'cli ran without error', e.message);
  }
}

process.stdout.write('\n' + passes + ' passed, ' + failures + ' failed\n');
process.exit(failures === 0 ? 0 : 1);
